"""目录树同步。

同步状态的定义是 ``(字节内容, mtime_ns)`` 二元组，每个文件条目按下面的规则
落到 :class:`SyncReport` 的某一类里（元素是相对 ``dst`` 的路径，
``os.path.join`` 风格，Windows 下是反斜杠）：

- 目标缺失               -> 复制内容 + 时间戳 + 属性，记入 ``created``
- 字节内容不同           -> 覆写 + 时间戳 + 属性，记入 ``updated``
- 内容相同但 mtime 不同  -> 只回写时间戳（保持目标 atime 不变），记入
  ``restamped``
- 目标多余               -> 删除（只读条目先清属性），记入 ``deleted``
- 其他无法完成的条目     -> 记入 ``failed``，并且**不中断**整次同步

条目填充会刷新父目录的 mtime，所以目录时间戳留到最后、按「先深层后浅层」
的顺序从源恢复，保证目标树的目录 mtime 与源一致。

``dry_run=True`` 时计算同样的报告，但不对目标树做任何写入（不创建、不覆写、
不删除、不写时间戳）。
"""

import logging
import os

from .attributes import FILE_ATTRIBUTE_READONLY, clear_readonly, set_attributes
from .copier import copy_stamp
from .stamps import snapshot_times

_LOG = logging.getLogger("wstamp")


class SyncReport:
    """一次同步的动作记录。列表元素是相对 ``dst`` 的路径。"""

    def __init__(self):
        self.created = []
        self.updated = []
        self.restamped = []
        self.deleted = []
        self.failed = []

    def __repr__(self):
        return (
            "SyncReport(created=%r, updated=%r, restamped=%r, deleted=%r, failed=%r)"
            % (self.created, self.updated, self.restamped, self.deleted, self.failed)
        )


def sync_tree(src, dst, dry_run=False):
    """把 ``src`` 目录树同步到 ``dst``，返回 :class:`SyncReport`。"""
    src = os.fspath(src)
    dst = os.fspath(dst)
    report = SyncReport()
    # 前序收集的 (dst_dir, rel, 源目录 mtime_ns)，最后逆序（先深层后浅层）恢复。
    dir_times = []
    _sync_dir(src, dst, "", report, dry_run, dir_times)
    _prune(src, dst, "", report, dry_run)
    if not dry_run:
        _restore_dir_times(dir_times, report)
    return report


def _join(base, rel):
    return os.path.join(base, rel) if rel else base


def _child(rel, name):
    return os.path.join(rel, name) if rel else name


def _record_failed(report, rel_path, exc):
    """记录一个无法完成的条目，同步继续。"""
    report.failed.append(rel_path)
    _LOG.warning("wstamp: %s (%s)", rel_path, exc)


def _sync_dir(src, dst, rel, report, dry_run, dir_times):
    src_dir = _join(src, rel)
    dst_dir = _join(dst, rel)

    if not dry_run:
        try:
            os.makedirs(dst_dir, exist_ok=True)
        except OSError as exc:
            if not rel:
                # 目标根目录都建不起来，整次同步没有意义。
                raise
            # 目标位置被同名文件占据之类：这个子树无法同步。
            _record_failed(report, rel, exc)
            return

    try:
        names = sorted(os.listdir(src_dir))
    except OSError as exc:
        if not rel:
            raise
        _record_failed(report, rel, exc)
        return

    dir_times.append((dst_dir, rel, os.stat(src_dir).st_mtime_ns))

    for name in names:
        src_path = os.path.join(src_dir, name)
        rel_path = _child(rel, name)
        if os.path.isdir(src_path):
            _sync_dir(src, dst, rel_path, report, dry_run, dir_times)
        else:
            _sync_file(src_path, os.path.join(dst, rel_path), rel_path, report, dry_run)


def _sync_file(src_path, dst_path, rel_path, report, dry_run):
    try:
        src_snap = snapshot_times(src_path)

        if os.path.isdir(dst_path):
            # 目标位置被同名目录占据，文件条目无法落地。
            _record_failed(report, rel_path, "target path is a directory: %s" % dst_path)
            return

        with open(src_path, "rb") as fh:
            src_bytes = fh.read()

        if not os.path.exists(dst_path):
            if not dry_run:
                copy_stamp(src_path, dst_path)
            report.created.append(rel_path)
            return

        # 快照必须取在读取内容之前：读取目标会刷新它的 atime，而 restamped
        # 分支要求 atime 保持原值。
        dst_snap = snapshot_times(dst_path)
        with open(dst_path, "rb") as fh:
            dst_bytes = fh.read()

        if src_bytes != dst_bytes:
            if not dry_run:
                copy_stamp(src_path, dst_path)
            report.updated.append(rel_path)
            return

        if dst_snap["mtime_ns"] != src_snap["mtime_ns"]:
            # 内容一致、mtime 不一致：只回写时间戳，atime 保持目标原值。
            if not dry_run:
                _write_times(dst_path, dst_snap["atime_ns"], src_snap["mtime_ns"])
            report.restamped.append(rel_path)
            return

        # 内容与 mtime 都一致：条目已同步，不做任何动作（只把比较读取时被刷
        # 新的 atime 还原回去，保证「无动作」在目标树上不可观测）。
        if not dry_run:
            _restore_atime(dst_path, dst_snap["atime_ns"])
    except Exception as exc:  # 单个条目的问题不能中断整次同步
        _record_failed(report, rel_path, exc)


def _prune(src, dst, rel, report, dry_run):
    dst_dir = _join(dst, rel)
    if not os.path.isdir(dst_dir):
        return
    src_dir = _join(src, rel)
    try:
        names = sorted(os.listdir(dst_dir))
    except OSError as exc:
        if rel:
            _record_failed(report, rel, exc)
        return
    for name in names:
        dst_path = os.path.join(dst_dir, name)
        rel_path = _child(rel, name)
        src_path = os.path.join(src_dir, name)
        if not os.path.exists(src_path):
            # 目标多余：删除（只读条目先清属性再删）。
            try:
                if not dry_run:
                    _remove(dst_path)
                report.deleted.append(rel_path)
            except Exception as exc:
                _record_failed(report, rel_path, exc)
        elif os.path.isdir(dst_path) and os.path.isdir(src_path):
            _prune(src, dst, rel_path, report, dry_run)


def _restore_dir_times(dir_times, report):
    """把目录 mtime 从源恢复回去（先深层后浅层）。

    前序遍历的逆序天然满足「子目录先于父目录」，所以父目录的时间戳总是最后
    写，不会被后续动作再刷掉。目录的 atime 保持目标自己的值。
    """
    for dst_dir, rel, mtime_ns in reversed(dir_times):
        if not os.path.isdir(dst_dir):
            continue
        try:
            _write_times(dst_dir, os.stat(dst_dir).st_atime_ns, mtime_ns)
        except Exception as exc:
            _record_failed(report, rel, exc)


def _write_times(path, atime_ns, mtime_ns):
    """写时间戳；目标带只读属性时先清掉、写完恢复原属性位。"""
    attrs = clear_readonly(path)
    try:
        os.utime(path, ns=(int(atime_ns), int(mtime_ns)))
    finally:
        if attrs & FILE_ATTRIBUTE_READONLY:
            set_attributes(path, attrs)


def _restore_atime(path, atime_ns):
    """把比较读取时被刷新的 atime 还原（尽力而为，不产生报告条目）。"""
    try:
        st = os.stat(path)
        if st.st_atime_ns == int(atime_ns):
            return
        _write_times(path, atime_ns, st.st_mtime_ns)
    except OSError as exc:
        _LOG.debug("wstamp: keep atime of %s failed (%s)", path, exc)


def _remove(path):
    """删除文件或整棵目录树；只读条目先清除属性再删。"""
    if os.path.isdir(path) and not os.path.islink(path):
        for name in sorted(os.listdir(path)):
            _remove(os.path.join(path, name))
        clear_readonly(path)
        os.rmdir(path)
    else:
        clear_readonly(path)
        os.remove(path)
